WITH valid AS (SELECT *, CASE WHEN status IN ('EXPIRED', 'CANCELLED') THEN 'Group A' ELSE 'Other' END AS status_group, UPPER(status) AS status_upper FROM subscriptions WHERE YEAR(start_date) = 2024), latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id, status ORDER BY end_date DESC, id) AS row_num FROM valid) t WHERE row_num = 1), cleaned AS (SELECT *, ROUND(DATEDIFF(start_date, end_date) / 30, 1) AS months_end_date_to_start_date, LENGTH(plan) AS plan_length FROM latest WHERE row_num >= 1), enriched AS (SELECT a.*, p.city FROM cleaned a LEFT JOIN customers p ON a.customer_id <=> p.id), latest_subscriptions AS (SELECT id, start_date, status, row_num, plan_length, city FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id, city ORDER BY start_date DESC, id) AS dedup_rank FROM enriched) t WHERE dedup_rank = 1), pivoted AS (SELECT * FROM (SELECT status, city, plan_length FROM latest_subscriptions) src PIVOT (MAX(plan_length) AS value_sum, COUNT(1) AS n FOR city IN ('Bangkok' AS bangkok, 'Singapore' AS singapore, 'New York' AS new_york))) SELECT status, bangkok_value_sum, singapore_value_sum, singapore_n, new_york_n FROM pivoted ORDER BY new_york_n NULLS LAST, bangkok_value_sum DESC;
